import fs from "fs";
import path from "path";
import https from "https";
import tls from "node:tls";
import { fileURLToPath } from "node:url";
import { startElapsedReporter } from "./utils/progress.js";
import { createTunneledConnection } from "./utils/tunnel.js";

/**
 * GitDiagram crawler — pull / status Mermaid architecture diagrams.
 *
 * GitDiagram (https://gitdiagram.com/<user>/<repo>) renders a GitHub repo as a
 * Mermaid flowchart generated by an LLM. This script caches the generated
 * diagram (mmd source) + explanation locally, mirroring deepwiki.com.ts.
 *
 * Usage: npx tsx scripts/gitdiagram.com.ts <command> <target>
 *   pull   <user/repo|url|all>   Fetch diagram.mmd + explanation.md into
 *                                <SITES_ROOT|data>/gitdiagram.com/<user>/<repo>/.
 *                                If the repo has no cached diagram yet, the
 *                                generation is triggered automatically (SSE).
 *   status <user/repo|url|all>   Show diagram state + local cache info.
 *
 * Environment:
 *   GITHUB_PAT    GitHub personal access token, required for private repos.
 *   GITDIAGRAM_PROXY / HTTPS_PROXY   HTTP CONNECT proxy for all requests.
 */

// Storage root anchored to the skill root (not process.cwd()), so `pull all`
// enumerates and writes to the same location regardless of where tsx is run.
function gdStoragePath(subPath: string = ""): string {
  // import.meta.dirname is this file's dir (scripts/); its parent is the skill root.
  const skillRoot = path.resolve(path.dirname(import.meta.dirname));
  const root = path.resolve(skillRoot, "data");
  return path.join(root, subPath);
}

/** Reject path-traversal / empty segments in user/repo. */
function validateSegment(seg: string): boolean {
  return seg !== "" && seg !== "." && seg !== ".." && !seg.includes("\\");
}

function parseRepoInfo(input: string): { user: string; repo: string } {
  // Handle URL: https://gitdiagram.com/user/repo or https://github.com/user/repo
  if (input.startsWith("http")) {
    const url = new URL(input);
    const parts = url.pathname.split("/").filter(Boolean);
    if (parts.length < 2 || !validateSegment(parts[0]!) || !validateSegment(parts[1]!)) {
      console.error("Invalid URL. Use gitdiagram.com/user/repo or github.com/user/repo.");
      process.exit(1);
    }
    return {
      user: parts[0]!,
      repo: parts[1]!.replace(/\.git$/, ""),
    };
  }

  // Handle user/repo
  const parts = input.split("/");
  if (parts.length < 2 || !validateSegment(parts[0]!) || !validateSegment(parts[1]!)) {
    console.error("Invalid repo format. Use user/repo or a full URL.");
    process.exit(1);
  }
  return {
    user: parts[0]!,
    repo: parts[1]!.replace(/\.git$/, ""),
  };
}

/**
 * List existing local repos as their on-disk path "user/repo".
 */
function listLocalRepos(): string[] {
  const root = gdStoragePath("gitdiagram.com");
  if (!fs.existsSync(root)) return [];
  const repos: string[] = [];
  for (const user of fs.readdirSync(root)) {
    const userDir = path.join(root, user);
    let isDir = false;
    try {
      isDir = fs.statSync(userDir).isDirectory();
    } catch {
      continue;
    }
    if (!isDir) continue;
    for (const repo of fs.readdirSync(userDir)) {
      try {
        if (fs.statSync(path.join(userDir, repo)).isDirectory()) {
          repos.push(`${user}/${repo}`);
        }
      } catch {
        continue;
      }
    }
  }
  return repos.sort();
}

// ---------------------------------------------------------------------------
// Network helpers (zero-dependency: node https + optional HTTP CONNECT proxy)
// ---------------------------------------------------------------------------

const PROXY_URL =
  process.env.GITDIAGRAM_PROXY || process.env.HTTPS_PROXY || process.env.https_proxy || "";

interface HttpResult {
  status: number;
  body: string;
}

/** HTTPS GET/POST with optional HTTP CONNECT proxy tunneling + 3xx follow. */
function httpRequest(
  method: "GET" | "POST",
  rawUrl: string,
  headers: Record<string, string>,
  body?: string,
  timeoutMs = 20000,
  proxyUrl = "",
): Promise<HttpResult> {
  return requestOnce(method, rawUrl, headers, body, timeoutMs, proxyUrl, 3);
}

/** One HTTP attempt; follows 3xx Location (max `redirectsLeft` hops). */
function requestOnce(
  method: "GET" | "POST",
  rawUrl: string,
  headers: Record<string, string>,
  body: string | undefined,
  timeoutMs: number,
  proxyUrl: string,
  redirectsLeft: number,
): Promise<HttpResult> {
  const u = new URL(rawUrl);
  const doRequest = (createConnection?: () => tls.TLSSocket) =>
    new Promise<HttpResult>((resolve, reject) => {
      const req = https.request(
        u,
        {
          method,
          headers: { ...headers },
          timeout: timeoutMs,
          ...(createConnection ? { createConnection } : {}),
        },
        (res) => {
          const status = res.statusCode ?? 0;
          const loc = res.headers.location;
          if (redirectsLeft > 0 && status >= 300 && status < 400 && loc) {
            // 301/302/303: POST falls back to GET without a body; 307/308 keep
            // method and body (GitDiagram's API migration uses 308).
            const nextMethod =
              method === "POST" && (status === 301 || status === 302 || status === 303)
                ? "GET"
                : method;
            res.resume();
            resolve(
              requestOnce(
                nextMethod,
                new URL(loc, rawUrl).toString(),
                headers,
                nextMethod === "GET" ? undefined : body,
                timeoutMs,
                proxyUrl,
                redirectsLeft - 1,
              ),
            );
            return;
          }
          const chunks: Buffer[] = [];
          res.on("data", (c) => chunks.push(c as Buffer));
          res.on("end", () => resolve({ status, body: Buffer.concat(chunks).toString("utf-8") }));
        },
      );
      req.on("timeout", () => req.destroy(new Error(`timeout after ${timeoutMs}ms: ${rawUrl}`)));
      req.on("error", reject);
      if (body) req.write(body);
      req.end();
    });

  if (!proxyUrl) return doRequest();

  // CONNECT tunnel + explicit TLS wrap: Node does NOT TLS-wrap custom
  // createConnection sockets, so the raw tunnel socket would send plaintext
  // HTTP to :443 and get "400 plain HTTP request was sent to HTTPS port".
  // createTunneledConnection hands back an already-secured socket.
  return createTunneledConnection(u, proxyUrl, timeoutMs).then((createConnection) =>
    doRequest(createConnection),
  );
}

// ---------------------------------------------------------------------------
// GitDiagram API
// ---------------------------------------------------------------------------

interface DiagramState {
  diagram: string | null;
  explanation: string | null;
  graph: unknown;
  latestSessionAudit: unknown;
  lastSuccessfulAt: string | null;
}

const GITHUB_PAT = process.env.GITHUB_PAT || "";

/** Query diagram-state (the only source of the mmd source text). */
async function fetchDiagramState(repoName: string): Promise<DiagramState> {
  const [user, repo] = repoName.split("/");
  const url = "https://gitdiagram.com/api/diagram-state";
  const headers: Record<string, string> = {
    "content-type": "application/json",
    origin: "https://gitdiagram.com",
    "sec-fetch-site": "same-origin",
    "user-agent": "github-read-repo/2.0.0",
    accept: "*/*",
  };
  const body = JSON.stringify({
    username: user,
    repo,
    ...(GITHUB_PAT ? { github_pat: GITHUB_PAT } : {}),
  });
  const res = await httpRequest("POST", url, headers, body, 20000, PROXY_URL);
  if (res.status !== 200) throw new Error(`HTTP ${res.status}`);
  try {
    return JSON.parse(res.body) as DiagramState;
  } catch {
    throw new Error(`unexpected body: ${res.body.slice(0, 120)}`);
  }
}

/** Trigger diagram generation via SSE and wait for the terminal message. */
async function generateDiagram(repoName: string): Promise<DiagramState> {
  const [user, repo] = repoName.split("/");
  const url = "https://gitdiagram.com/api/generate/stream";
  const body = JSON.stringify({
    username: user,
    repo,
    ...(GITHUB_PAT ? { github_pat: GITHUB_PAT } : {}),
  });

  console.log(`  triggering generation via SSE...`);
  const stop = startElapsedReporter(`等待 ${repoName} 的架构图生成（SSE）`);
  let sse: SseMessage[];
  try {
    sse = await fetchSse(url, body, 240_000);
  } finally {
    stop();
  }
  // Terminal states: complete carries the diagram; error carries the reason.
  const terminal = sse.find((m) => m.status === "complete" || m.status === "error");
  if (!terminal) throw new Error("generation stream ended without a terminal message");
  if (terminal.status === "error") {
    const reason = terminal.error || terminal.error_code || "unknown error";
    // GitDiagram maps upstream GitHub "not found" to a private-repo hint even
    // for public repos; its shared GitHub quota being exhausted looks identical.
    // Give the caller an actionable hint instead of the raw message alone.
    const hint = GITHUB_PAT
      ? `Note: the repo may still be private/unreachable with the provided GITHUB_PAT — check the token's Contents: Read-only permission.`
      : `Note: for private repos, set GITHUB_PAT (GitHub token with Contents: Read-only). For public repos, a "not found" usually means GitDiagram's GitHub access is temporarily limited — retry later, or open https://gitdiagram.com/${repoName} in a browser to trigger it manually.`;
    throw new Error(`generation failed: ${reason}\n    ${hint}`);
  }
  return {
    diagram: typeof terminal.diagram === "string" ? terminal.diagram : null,
    explanation: typeof terminal.explanation === "string" ? terminal.explanation : null,
    graph: terminal.graph ?? null,
    latestSessionAudit: terminal.latest_session_audit ?? null,
    lastSuccessfulAt: typeof terminal.generated_at === "string" ? terminal.generated_at : null,
  };
}

interface SseMessage {
  status: string;
  [key: string]: unknown;
}

/** Consume an SSE response (following 3xx Location, via proxy if set). */
async function fetchSse(rawUrl: string, body: string, timeoutMs: number): Promise<SseMessage[]> {
  let currentUrl = rawUrl;
  for (let hop = 0; hop < 3; hop++) {
    const u = new URL(currentUrl);
    const createConnection = PROXY_URL
      ? await createTunneledConnection(u, PROXY_URL, timeoutMs)
      : undefined;
    const outcome = await new Promise<{ status: number; messages: SseMessage[]; location?: string }>(
      (resolve, reject) => {
        const messages: SseMessage[] = [];
        const req = https.request(
          u,
          {
            method: "POST",
            headers: {
              "content-type": "application/json",
              accept: "text/event-stream",
              "user-agent": "github-read-repo/2.0.0",
            },
            timeout: timeoutMs,
            ...(createConnection ? { createConnection } : {}),
          },
          (res) => {
            const status = res.statusCode ?? 0;
            const loc = res.headers.location;
            if (status >= 300 && status < 400 && loc) {
              res.resume();
              resolve({ status, messages, location: new URL(loc, currentUrl).toString() });
              return;
            }
            if (status !== 200) {
              let errBody = "";
              res.on("data", (c) => (errBody += c.toString("utf-8")));
              res.on("end", () => reject(new Error(`HTTP ${status}: ${errBody.slice(0, 200)}`)));
              return;
            }
            let buffer = "";
            res.on("data", (c) => {
              buffer += c.toString("utf-8");
              // Split on event boundaries (blank line). Keep remainder.
              let idx: number;
              while ((idx = buffer.indexOf("\n\n")) >= 0) {
                const event = buffer.slice(0, idx);
                buffer = buffer.slice(idx + 2);
                for (const line of event.split("\n")) {
                  if (!line.startsWith("data:")) continue;
                  const payload = line.slice(5).trim();
                  if (!payload) continue;
                  try {
                    const msg = JSON.parse(payload) as SseMessage;
                    messages.push(msg);
                    // Cheap progress print for long generations.
                    if (msg.status === "started") console.log("  generation started");
                  } catch {
                    // ignore non-JSON data lines (e.g. comments)
                  }
                }
              }
            });
            res.on("end", () => resolve({ status, messages }));
            res.on("error", reject);
          },
        );
        req.on("timeout", () => req.destroy(new Error(`SSE timeout after ${timeoutMs}ms`)));
        req.on("error", reject);
        req.write(body);
        req.end();
      },
    );
    if (outcome.location) {
      currentUrl = outcome.location;
      continue;
    }
    return outcome.messages;
  }
  throw new Error(`SSE redirect loop for ${rawUrl}`);
}

// ---------------------------------------------------------------------------
// Local cache helpers
// ---------------------------------------------------------------------------

function localPullInfo(localName: string): { date: string; mtimeMs: number } | undefined {
  const [user, repo] = localName.split("/");
  const dir = gdStoragePath(path.join("gitdiagram.com", user!, repo!));
  try {
    const st = fs.statSync(path.join(dir, "diagram.mmd"));
    return { date: st.mtime.toISOString().slice(0, 10), mtimeMs: st.mtimeMs };
  } catch {
    return undefined;
  }
}

/** Atomic write: write to temp file, then rename into place. */
function atomicWrite(dir: string, name: string, content: string): void {
  const tmp = path.join(dir, `.${name}.tmp`);
  fs.writeFileSync(tmp, content, "utf-8");
  fs.renameSync(tmp, path.join(dir, name));
}

async function pullRepo(localName: string): Promise<void> {
  const [user, repoRaw] = localName.split("/");
  const repoName = `${user!}/${repoRaw!.replace(/\.git$/, "")}`;
  const targetDir = gdStoragePath(path.join("gitdiagram.com", user!, repoRaw!));

  console.log(`Querying diagram state for ${repoName}...`);
  let state: DiagramState;
  try {
    state = await fetchDiagramState(repoName);
  } catch (e) {
    throw new Error(`diagram-state query failed: ${e instanceof Error ? e.message : String(e)}`);
  }

  if (!state.diagram) {
    console.log(`  no cached diagram for ${repoName} — generating...`);
    state = await generateDiagram(repoName);
  } else {
    console.log(`  cached diagram available (${state.diagram.length} chars)`);
  }

  if (!state.diagram) {
    throw new Error(`generation returned no diagram for ${repoName}`);
  }

  console.log(`Saving files to ${targetDir}...`);
  fs.mkdirSync(targetDir, { recursive: true });

  const meta = {
    generatedAt: state.lastSuccessfulAt ?? new Date().toISOString(),
    pulledAt: new Date().toISOString(),
    diagramBytes: Buffer.byteLength(state.diagram, "utf-8"),
    explanationBytes: state.explanation ? Buffer.byteLength(state.explanation, "utf-8") : 0,
  };

  atomicWrite(targetDir, "diagram.mmd", state.diagram);
  atomicWrite(targetDir, "explanation.md", state.explanation ?? "");
  atomicWrite(targetDir, "meta.json", JSON.stringify(meta, null, 2));
  console.log(`Saved: diagram.mmd (${meta.diagramBytes} bytes)${state.explanation ? ", explanation.md" : ""}, meta.json`);
  console.log(`\nSuccessfully pulled diagram for ${repoName}`);
}

async function statusOne(localName: string): Promise<void> {
  const [user, repoRaw] = localName.split("/");
  const repoName = `${user!}/${repoRaw!.replace(/\.git$/, "")}`;
  console.log(`== ${repoName} ==`);
  const local = localPullInfo(localName);

  let state: DiagramState;
  try {
    state = await fetchDiagramState(repoName);
  } catch (e) {
    console.log(`  diagram API : error (${e instanceof Error ? e.message : String(e)})`);
    console.log("");
    return;
  }

  if (state.diagram) {
    const bits = [`generated ${state.lastSuccessfulAt?.slice(0, 10) ?? "?"}`];
    console.log(`  diagram API : cached ✓  (${state.diagram.length} chars)  ${bits.join(", ")}`);
  } else {
    console.log(`  diagram API : NOT generated (pull will trigger generation)`);
  }

  console.log(`  local copy  : ${local ? `pulled ${local.date}` : "none"}`);

  if (state.diagram && !local) {
    console.log(`\n  → Generated but not pulled yet:\n      npx tsx scripts/gitdiagram.com.ts pull ${repoName}`);
  }
  console.log("");
}

async function statusAll(): Promise<void> {
  const targets = listLocalRepos();
  if (targets.length === 0) {
    console.error("No local repos found. Run pull <user/repo> to fetch one first.");
    process.exit(1);
  }
  for (const t of targets) {
    await statusOne(t);
  }
}

const USAGE = `GitDiagram crawler — pull / status Mermaid architecture diagrams

Usage: npx tsx scripts/gitdiagram.com.ts <command> <target>
       (legacy shorthand: a bare "user/repo" or URL is treated as "pull")

Commands:
  pull  <user/repo|url|all>   Download diagram.mmd + explanation.md into
                              <SITES_ROOT|data>/gitdiagram.com/<user>/<repo>/.
                              Repos without a cached diagram trigger generation.
  status <user/repo|url|all>  Show diagram state + local cache info.

Environment:
  GITHUB_PAT    GitHub PAT for private repos (optional, never hardcoded)
  GITDIAGRAM_PROXY / HTTPS_PROXY   HTTP CONNECT proxy for all requests

Examples:
  npx tsx scripts/gitdiagram.com.ts status encode/fastapi
  npx tsx scripts/gitdiagram.com.ts pull ahmedkhaleel2004/gitdiagram
  npx tsx scripts/gitdiagram.com.ts pull all`;

async function main() {
  // Junction-aware startup hint: the skill may be invoked through a junction
  // whose path differs from the real path the cache is written under.
  console.error(`技能根（真实路径）: ${fs.realpathSync(path.resolve(path.dirname(import.meta.dirname)))}`);

  const argv = process.argv.slice(2);
  const [cmd, targetRaw] = argv;
  const COMMANDS = ["pull", "status"];

  if (cmd === "help" || cmd === "--help" || cmd === "-h") {
    console.log(USAGE);
    process.exit(0);
  }

  // Legacy shorthand: a bare "user/repo" or URL means pull.
  const command = targetRaw ? (cmd as string) : "pull";
  const target = targetRaw ?? cmd;

  if (!target || !COMMANDS.includes(command) || (!targetRaw && cmd !== undefined && COMMANDS.includes(cmd))) {
    console.log(USAGE);
    process.exit(target ? 0 : 1);
  }

  if (command === "pull") {
    let targets: string[];
    if (target === "*" || target === "all") {
      targets = listLocalRepos();
      if (targets.length === 0) {
        console.error("No local repos found. Run pull <user/repo> to fetch one first.");
        process.exit(1);
      }
    } else {
      const { user, repo } = parseRepoInfo(target);
      targets = [`${user}/${repo}`];
    }

    let failed = 0;
    for (const t of targets) {
      try {
        await pullRepo(t);
      } catch (e) {
        console.error(`\n!!! Failed to pull ${t}: ${e instanceof Error ? e.message : String(e)}`);
        failed++;
      }
    }
    console.log(`\n=== Done: ${targets.length - failed}/${targets.length} repos pulled, ${failed} failed ===`);
    // Runtime/network failures exit 2 per SKILL.md's exit-code contract
    // (0 success, 1 input error, 2 runtime / I/O / network).
    if (failed > 0) process.exit(2);
    return;
  }

  if (command === "status") {
    if (target === "*" || target === "all") {
      await statusAll();
    } else {
      const { user, repo } = parseRepoInfo(target);
      await statusOne(`${user}/${repo}`);
    }
    return;
  }
}

// Allow importing this module as a library (main() never runs then).
const isMain =
  process.argv[1] === fileURLToPath(import.meta.url) ||
  process.argv[1]?.endsWith("gitdiagram.com.ts") ||
  process.argv[1]?.endsWith("gitdiagram.com.js");

if (isMain) {
  main().catch((error) => {
    console.error("Fatal Error:", error instanceof Error ? error.message : String(error));
    process.exit(2);
  });
}
